// Host test of the stale-settings guard (np_settings_guard.h) against real files: tests/fixtures/np-player/ holds what the 1.0 and 1.1 Settings screens wrote
// (generated by compiling each release's own np_settings.cpp: v1.0-* from 6f79465, v1.1-* from 5421c34 of the public history).
//   c++ -std=c++17 -I../src test_settings_guard.cpp ../src/np_settings_guard.cpp ../src/np_settings.cpp -o t && ./t fixtures/np-player
#include "np_settings.h"
#include "np_settings_guard.h"

#include <cstdio>
#include <cstring>
#include <dirent.h>
#include <fstream>
#include <set>
#include <sstream>
#include <string>
#include <vector>

using namespace NpSettingsGuard;

static int g_failed = 0, g_checks = 0;
#define CHECK(c) do { ++g_checks; if (!(c)) { ++g_failed; std::printf("FAIL %s:%d  %s\n", __FILE__, __LINE__, #c); } } while (0)

static const char* kVersion = "1.3.0";
static const char* kBuild = "0123456789abcdef";

static std::string Read(const std::string& path) {
    std::ifstream f(path, std::ios::binary);
    std::stringstream s;
    s << f.rdbuf();
    return s.str();
}

// the active (not commented) value of a key in a text, or "<none>"
static std::string Active(const std::string& text, const char* key) {
    std::stringstream in(text);
    std::string line, found = "<none>";
    while (std::getline(in, line)) {
        if (!line.empty() && line[0] == '#') continue;
        const size_t eq = line.find('=');
        if (eq != std::string::npos && line.substr(0, eq) == key) found = line.substr(eq + 1);
    }
    return found;
}
static bool HasLine(const std::string& text, const std::string& needle) { return text.find(needle) != std::string::npos; }
static std::string FirstLine(const std::string& text) { return text.substr(0, text.find('\n')); }

static std::string Run(const std::string& in, Report& r) { return Migrate(in, kVersion, kBuild, r); }

static std::vector<std::string> Files(const std::string& dir) {
    std::vector<std::string> out;
    if (DIR* d = opendir(dir.c_str())) {
        while (dirent* e = readdir(d)) {
            const std::string n = e->d_name;
            if (n.size() > 4 && n.substr(n.size() - 4) == ".txt") out.push_back(n);
        }
        closedir(d);
    }
    return out;
}

static int Choice(const NpSettings::State& s, const char* title) { return s.choice[NpSettings::OptionIndex(title)]; }

int main(int argc, char** argv) {
    const std::string dir = argc > 1 ? argv[1] : "fixtures/np-player";
    const std::vector<std::string> files = Files(dir);
    CHECK(files.size() >= 40);

    // ---- the named 1.1 files
    {
        Report r;
        const std::string in = Read(dir + "/v1.1-preset-0-PERFORMANCE.txt");
        CHECK(Active(in, "MSC_VITA_RENDER") == "640x362");   // (the file really is the stale one)
        const std::string out = Run(in, r);
        CHECK(!r.current && r.changed && r.turnedOff == 1);
        CHECK(FirstLine(out) == "# np-player.txt written by 1.3.0 build 0123456789abcdef");
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>");
        CHECK(Active(out, "MSC_PERFORMANCE_MODE") == "1");   // the crowd choice still means the same
        CHECK(HasLine(out, "# 1.3 turned off: MSC_VITA_RENDER=640x362"));
        CHECK(LoadingLine(r) != nullptr && std::string(LoadingLine(r)).size() <= 46);
        CHECK(r.backupName == "np-player.before-1.3.txt");
        CHECK(!r.log.empty() && r.log[0].find("no stamp") != std::string::npos);
    }
    {
        Report r;
        const std::string out = Run(Read(dir + "/v1.1-preset-2-QUALITY.txt"), r);
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>");
        CHECK(Active(out, "MSC_FPS") == "30");   // a steady 30 is a real choice
        CHECK(r.turnedOff == 1);
    }
    {
        Report r;
        const std::string in = Read(dir + "/v1.1-preset-1-DEFAULT.txt");
        const std::string out = Run(in, r);
        CHECK(r.turnedOff == 0 && LoadingLine(r) == nullptr);   // nothing to say to the player; the file is only stamped
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>");
    }
    {   // a player who went through the screen: every real choice survives byte for byte
        Report r;
        const std::string in = Read(dir + "/v1.1-player-choices.txt");
        const std::string out = Run(in, r);
        CHECK(r.turnedOff == 0 && LoadingLine(r) == nullptr);
        for (const char* k : {"MSC_VITA_UPSCALE", "NP_WIDESCREEN", "MSC_CONTROLS", "NP_POINTER_SPEED"})
            CHECK(Active(out, k) == Active(in, k) && Active(in, k) != "<none>");
    }
    {   // 1.0
        Report r;
        const std::string out = Run(Read(dir + "/v1.0-preset-0-PERFORMANCE.txt"), r);
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>" && Active(out, "MSC_FPS") == "<none>" && Active(out, "MSC_PERFORMANCE_MODE") == "1");
        CHECK(r.turnedOff == 2);
    }

    // ---- every real file: the stale keys go, nothing else moves, the text round-trips through the Settings screen's own reader
    std::set<std::string> staleRows = {"FRAME RATE", "CORE PLAN", "DEPTH OF FIELD"};   // (set18: RESOLUTION and ANTI-ALIASING went too; 1.3 prune: the rows that went from the screen are not here any more; DEPTH OF FIELD lost "AS GAME", which the guard turns into the default)
    int migrated = 0, quiet = 0;
    for (const std::string& f : files) {
        const std::string in = Read(dir + "/" + f);
        Report r;
        const std::string out = Run(in, r);
        ++migrated;
        CHECK(FirstLine(out).compare(0, 27, "# np-player.txt written by ") == 0);
        for (const char* gone : {"MSC_VITA_RENDER", "MSC_VITA_MSAA", "MSC_VITA_ANISO", "MSC_FPS_REPLAY", "MSC_FX_LOWRES", "MSC_FX_LOWRES_SCENES", "MSC_FX_LOWRES_MINPX"}) CHECK(Active(out, gone) == "<none>");
        CHECK(Active(out, "NP_MENU_NAV") != "0" && Active(out, "MSC_DOF") != "1");   // (the 1.3 prune rules: the screens need the menu moves; AS GAME is the default's picture)
        CHECK(Active(out, "MSC_PLAN") != "A");
        // idempotent, and what it wrote is current
        Report again;
        const std::string twice = Run(out, again);
        CHECK(again.current && twice == out);
        // no key outside the rules changes its value
        for (const char* keep : {"MSC_CONTROLS", "MSC_REAR_TOUCH", "NP_WIDESCREEN", "MSC_LAN_MODE", "MSC_GAME_FIXES", "MSC_UNLOCK_CAPTAINS", "MSC_UNLOCK_STADIUMS", "MSC_VITA_UPSCALE",
                                 "NP_POINTER_SPEED", "NP_TOUCH_POINTER", "MSC_MEGA_POINTER_SPEED", "MSC_TOUCH_SAVE", "MSC_PERFORMANCE_MODE", "MSC_LAN_DIALOG"})
            CHECK(Active(out, keep) == Active(in, keep) || (std::string(keep) == "MSC_PERFORMANCE_MODE"));
        // the Settings screen reads both files; only rows that own a turned-off key may differ
        NpSettings::State a, b;
        NpSettings::Load(a, in.c_str());
        NpSettings::Load(b, out.c_str());
        for (int o = 0; o < NpSettings::OptionCount(); ++o)
            if (a.choice[o] != b.choice[o]) CHECK(staleRows.count(NpSettings::GetOption(o).title) == 1);
        // after the migration no row of the file pins a fixed picture size
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>" && Choice(b, "FRAME RATE") >= -1);
        if (r.turnedOff == 0) ++quiet;
        // and the Settings screen's save of the migrated file is stable (it keeps the stamp)
        std::string saved;
        CHECK(NpSettings::Serialize(b, saved));
        Report afterSave;
        const std::string stamped = Stamped(saved, kVersion, kBuild);
        Run(stamped, afterSave);
        CHECK(afterSave.current);
    }
    CHECK(migrated >= 40 && quiet >= 5);

    // ---- the console test kit's own files (tools/console-1.2/env, lan): stamped, so the guard of the isolated test app leaves every switch of a run in place
    if (argc > 2) {
        int kit = 0;
        for (const std::string& n : Files(argv[2])) {
            const std::string in = Read(std::string(argv[2]) + "/" + n);
            Report r;
            CHECK(Run(in, r) == in && r.current && !r.changed);
            // 1.3 prune: a kit file names keys of rows that went (MSC_FX_GOV, MSC_VITA_CORE3, ...): the screen reads it, and a save without a change gives back every line no row owns
            NpSettings::State st;
            NpSettings::Load(st, in.c_str());
            std::string saved;
            CHECK(NpSettings::Serialize(st, saved));
            for (const char* retired : {"MSC_FX_GOV", "MSC_VITA_CORE3", "MSC_DYNRES", "MSC_PICTURE_HOLD", "MSC_FX_GLOW", "MSC_VGX_LA88", "MSC_SHADOW_PLAY", "MSC_VITA_ANISO", "MSC_FPS_REPLAY"}) {
                const std::string key = std::string(retired) + "=";
                size_t inN = 0, outN = 0;
                for (size_t at = in.find(key); at != std::string::npos; at = in.find(key, at + 1)) inN += (at == 0 || in[at - 1] == '\n');
                for (size_t at = saved.find(key); at != std::string::npos; at = saved.find(key, at + 1)) outN += (at == 0 || saved[at - 1] == '\n');
                CHECK(inN == outN);
            }
            ++kit;
        }
        CHECK(kit > 100);
    }

    // ---- the stamp
    {
        Report r;
        const std::string mine = std::string(StampLine(kVersion, kBuild)) + "\nMSC_VITA_RENDER=640x362\n";
        CHECK(Run(mine, r) == mine && r.current && !r.changed);   // a 1.3 file: a real choice of the 1.3 screen is kept
        const std::string newer = "# np-player.txt written by 1.4.0 build ff\nMSC_VITA_RENDER=480x272\n";
        CHECK(Run(newer, r) == newer && r.current);               // a newer file under an older build is left alone
        // a later build must not undo the choices the 1.3 screen itself wrote (a stamp of 1.3.0 or later is never migrated, whatever this build's version)
        {
            Report later;
            const std::string chosen = "# np-player.txt written by 1.3.0 build aa\nMSC_VITA_RENDER=960x544\nMSC_DYNRES=off\nMSC_PLAN=A\n";
            CHECK(Migrate(chosen, "1.3.1", kBuild, later) == chosen && later.current && !later.changed);
            CHECK(Migrate(chosen, "1.4.0", kBuild, later) == chosen && later.current && later.turnedOff == 0);
            const std::string stale = "# np-player.txt written by 1.2.9\nMSC_VITA_RENDER=960x544\n";
            Migrate(stale, "1.4.0", kBuild, later);
            CHECK(!later.current && later.turnedOff == 1);   // (a stamp older than 1.3.0 is still a stale file)
        }
        const std::string older = "# np-player.txt written by 1.1.0\nMSC_VITA_RENDER=960x544\nMSC_CONTROLS=classic\n";
        const std::string out = Run(older, r);
        CHECK(!r.current && r.turnedOff == 1 && Active(out, "MSC_CONTROLS") == "classic" && HasLine(out, "# 1.3 turned off: MSC_VITA_RENDER=960x544"));
        CHECK(Stamped("a=1\n" + std::string(StampLine("1.0.0", "")) + "\nb=2\n", kVersion, kBuild) == StampLine(kVersion, kBuild) + "\na=1\nb=2\n");
        CHECK(!ReadStamp("MSC_FPS=30\n").valid && ReadStamp(StampLine("1.2.7", "")).valid);
        CHECK(ReadStamp(StampLine("1.2.7", "x") + "\n").minor == 2);
        CHECK(ParseVersion("1.3.0").valid && !ParseVersion("1.3.x").valid && !ParseVersion("").valid && !ParseVersion("1..3").valid && !ParseVersion("1.3.").valid);
        CHECK(Compare(ParseVersion("1.3.0"), ParseVersion("1.10.0")) < 0 && Compare(ParseVersion("1.3.0"), ParseVersion("1.3.0")) == 0);
        CHECK(BackupName("1.3.0") == "np-player.before-1.3.txt");
    }

    // ---- 1.3 prune: the rules for the rows that went (only in files older than 1.3.0; a stamped 1.3 file is never touched)
    {
        Report r;
        const std::string in = "MSC_DOF=1\nMSC_FPS_REPLAY=30\nMSC_FX_LOWRES=0\nMSC_FX_LOWRES_SCENES=nis\nMSC_FX_LOWRES_MINPX=480000\nMSC_VITA_ANISO=3\nNP_MENU_NAV=0\nMSC_FPS=30\nMSC_PERFORMANCE_MODE=1\n";
        const std::string out = Run(in, r);
        CHECK(r.turnedOff == 7 && !r.current && r.changed && LoadingLine(r));
        for (const char* gone : {"MSC_DOF", "MSC_FPS_REPLAY", "MSC_FX_LOWRES", "MSC_FX_LOWRES_SCENES", "MSC_FX_LOWRES_MINPX", "MSC_VITA_ANISO", "NP_MENU_NAV"}) CHECK(Active(out, gone) == "<none>");
        CHECK(Active(out, "MSC_FPS") == "30" && Active(out, "MSC_PERFORMANCE_MODE") == "1");   // a real choice and the crowd stay
        CHECK(HasLine(out, "# 1.3 turned off: NP_MENU_NAV=0") && HasLine(out, "# 1.3 turned off: MSC_FX_LOWRES_SCENES=nis"));
        // values that are a real choice, or no choice of a removed row, are not touched
        Report q;
        const std::string keep = "MSC_DOF=0\nMSC_DOF=lazy\nNP_MENU_NAV=1\nMSC_FX_LOWRES=2\nMSC_FPS=30\n";
        const std::string kept = Run(keep, q);
        CHECK(q.turnedOff == 0 && Active(kept, "MSC_DOF") == "lazy" && Active(kept, "NP_MENU_NAV") == "1" && Active(kept, "MSC_FX_LOWRES") == "2");
        CHECK(HasLine(kept, "MSC_DOF=0"));
        // stamped 1.3.0: the same lines stay
        Report s;
        const std::string stamped = StampLine(kVersion, kBuild) + "\n" + in;
        CHECK(Run(stamped, s) == stamped && s.current && s.turnedOff == 0);
    }

    // ---- odd files: never fatal
    {
        Report r;
        std::string out = Run("", r);
        CHECK(out == StampLine(kVersion, kBuild) + "\n" && r.turnedOff == 0);
        out = Run("# only a comment\r\n\r\n=novalue\r\nMSC_VITA_RENDER=640x362\r\nMSC_FUTURE_THING=7\r\nNP_LANG=4\r\n  MSC_DYNRES = off  \r\n", r);
        CHECK(Active(out, "MSC_VITA_RENDER") == "<none>" && Active(out, "MSC_DYNRES") == "<none>");   // CRLF and blanks
        CHECK(Active(out, "NP_LANG") == "4" && Active(out, "MSC_FUTURE_THING") == "7");              // the player's language and an unknown key survive
        CHECK(r.unknown == 1 && r.turnedOff == 2);                                                    // the unknown key is counted, not an error
        std::string big(40000, 'x');
        out = Run("MSC_VITA_RENDER=" + big + "\nMSC_FPS=auto\n" + big, r);
        CHECK(r.turnedOff == 2);
        out = Run(std::string("\0\1\2=\n\xff\xfe\n", 8), r);   // binary junk
        CHECK(!out.empty());
        out = Run("MSC_PICTURE=performance\n", r);
        CHECK(Active(out, "MSC_PICTURE") == "<none>" && Active(out, "MSC_PERFORMANCE_MODE") == "1" && r.added == 1);
        out = Run("MSC_PICTURE=performance\nMSC_PERFORMANCE_MODE=0\n", r);
        CHECK(Active(out, "MSC_PERFORMANCE_MODE") == "0" && r.added == 0);   // a line the player wrote is not overridden
        out = Run("MSC_PICTURE=lock60\nMSC_FPS=30\nMSC_PLAN=S\nMSC_PLAN=A\n", r);
        CHECK(Active(out, "MSC_PICTURE") == "lock60" && Active(out, "MSC_FPS") == "30" && Active(out, "MSC_PLAN") == "S" && HasLine(out, "# 1.3 turned off: MSC_PLAN=A"));
    }
    std::printf("%d checks, %d failed\n", g_checks, g_failed);
    return g_failed ? 1 : 0;
}
